{

    internal InnerTelemetryRuleMskMonitoringParametersFactory MskMonitoringParametersFactory { get; set; }

    internal InnerTelemetryRuleELBLoadBalancerLoggingParametersFactory ELBLoadBalancerLoggingParametersFactory { get; set; }

    internal InnerTelemetryRuleVPCFlowLogParametersFactory VPCFlowLogParametersFactory { get; set; }

    internal InnerTelemetryRuleCloudtrailParametersFactory CloudtrailParametersFactory { get; set; }

    internal InnerTelemetryRuleWAFLoggingParametersFactory WAFLoggingParametersFactory { get; set; }

    internal InnerTelemetryRuleLogDeliveryParametersFactory LogDeliveryParametersFactory { get; set; }

    protected override Humidifier.ObservabilityAdmin.TelemetryRuleTypes.TelemetryDestinationConfiguration Create()
    {
        var telemetryDestinationConfigurationResult = CreateTelemetryDestinationConfiguration();
        factoryAction?.Invoke(telemetryDestinationConfigurationResult);

        return telemetryDestinationConfigurationResult;
    }

    private Humidifier.ObservabilityAdmin.TelemetryRuleTypes.TelemetryDestinationConfiguration CreateTelemetryDestinationConfiguration()
    {
        var telemetryDestinationConfigurationResult = new Humidifier.ObservabilityAdmin.TelemetryRuleTypes.TelemetryDestinationConfiguration();

        return telemetryDestinationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.ObservabilityAdmin.TelemetryRuleTypes.TelemetryDestinationConfiguration result)
    {
        base.CreateChildren(result);

        result.MskMonitoringParameters ??= MskMonitoringParametersFactory?.Build();
        result.ELBLoadBalancerLoggingParameters ??= ELBLoadBalancerLoggingParametersFactory?.Build();
        result.VPCFlowLogParameters ??= VPCFlowLogParametersFactory?.Build();
        result.CloudtrailParameters ??= CloudtrailParametersFactory?.Build();
        result.WAFLoggingParameters ??= WAFLoggingParametersFactory?.Build();
        result.LogDeliveryParameters ??= LogDeliveryParametersFactory?.Build();
    }

} // End Of Class

